import app from 'flarum/common/app';

/**
 * Advent calendars, from the `giveaway-calendars` JSON:API type. A door's
 * content only comes back for doors the viewer has opened; every other door
 * is its number, its state and when it opens.
 */

/** A door as the builder edits it (managers only). */

const TYPE = 'giveaway-calendars';
function base() {
  return `${app.forum.attribute('apiUrl')}/${TYPE}`;
}
function flat(resource) {
  return {
    id: resource.id,
    ...resource.attributes
  };
}
export function showCalendar(slug) {
  return app.request({
    method: 'GET',
    url: `${base()}/${encodeURIComponent(slug)}`
  }).then(r => flat(r.data));
}
export function listCalendars() {
  return app.request({
    method: 'GET',
    url: base()
  }).then(r => r.data.map(flat));
}
export function openDoor(id, day, joker = false) {
  return app.request({
    method: 'POST',
    url: `${base()}/${id}/open`,
    body: {
      day,
      joker
    }
  }).then(r => flat(r.data));
}
export function setReminder(id, on) {
  return app.request({
    method: 'POST',
    url: `${base()}/${id}/remind`,
    body: {
      on
    }
  }).then(r => flat(r.data));
}
export function saveCalendar(attributes, id) {
  return app.request({
    method: id ? 'PATCH' : 'POST',
    url: id ? `${base()}/${id}` : base(),
    body: {
      data: {
        type: TYPE,
        ...(id ? {
          id
        } : {}),
        attributes
      }
    }
  }).then(r => flat(r.data));
}
export function deleteCalendar(id) {
  return app.request({
    method: 'DELETE',
    url: `${base()}/${id}`
  });
}

/**
 * The doors in a fixed shuffled order, the same for everyone (seeded by the
 * calendar's id), so the grid reads like a real advent calendar rather than
 * a list.
 */
export function shuffled(items, seed) {
  const out = items.slice();
  let s = seed >>> 0 || 1;
  const next = () => {
    // mulberry32
    s = s + 0x6d2b79f5 >>> 0;
    let t = s;
    t = Math.imul(t ^ t >>> 15, t | 1);
    t ^= t + Math.imul(t ^ t >>> 7, t | 61);
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(next() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}
flarum.reg.add('ernestdefoe-giveaways', 'common/advent', { showCalendar: showCalendar,listCalendars: listCalendars,openDoor: openDoor,setReminder: setReminder,saveCalendar: saveCalendar,deleteCalendar: deleteCalendar,shuffled: shuffled, });